  return M.spd * (H?.tempo || 1) * (H && H.stamina != null && H.stamina <= 0 ? 0.7 : 1) * (c.mounted.kind === 'mech_horse' && (S.mount?.oiled || 0) + 5 < (S.day | 0) ? 0.6 : 1);
