    const a = rnd() * 6.283, x = at ? at.x + (i ? Math.cos(a) * 24 : 22) : p.x + Math.cos(a) * R, y = at ? at.y + (i ? Math.sin(a) * 24 : 0) : p.y + Math.sin(a) * R;
