// Todesritter (Nutzer): sein Pferd wird zum Totenross; wer keins hat, bekommt einmal eins
const A_codexCode = c => { if (String(c).trim().toUpperCase() !== 'NACHTGLAS') return false; S.flags.codexAll = true; return true; };
