    let left = Math.round((x1 - x0 + 1) * (y1 - y0 + 1) / (P.perHead || 90)) - (GUARD_POSTS[town]?.posts.length || 0) - (P.lord === 'aurel' ? AUREL_GUARDS : 0) - named - hs.length;   // S12: Automaten zählen mit
