  const vs = S.ents.world.filter(c => c.villager && c.name).sort((a, b) => (a.id < b.id ? -1 : 1));
  const named = S.ents.world.filter(c => (c.kind === 'npc' || c.kind === 'player') && !c.villager && c.name).map(c => c.name.split(' ')[0]);
  const used = {};
