  if (S.map === 'world' && dist(e, S.player) < 420) { float(e, 'Wildbret', 'rgba(210,180,120,ALPHA)'); log(`${e.name} (Jäger) bringt Wild und Felle aus ${e.plan.hunt.where} zum Markt.`, 'world'); }
