      if (h < 18.5) return flog ? [FL_AT.post[0] - 4 + (i % 4) * 2, FL_AT.post[1] + 4 + ((i / 4) | 0) * 2, 'watch'] : [ax - 6 + (i % 4) * 3, ay - 2 + ((i / 4) | 0) * 3, 'appell'];
