  const now = performance.now(); z.aim = Math.atan2(v.y - z.y, v.x - z.x);
  if ((z._lash || 0) < now) { z._lash = now + 1700; act(z, 'work', 700, v); act(v, 'kneel', 1500); fx(v.x, v.y - 14, 'blood', 3); if (dist(z, S.player) < 420) sfx('hit', 0.25, 0.6); }
