    fortState().flogStop = S.day | 0; S.ents.world = S.ents.world.filter(e => !e.flogVictim); if (rep) for (const [f, n] of Object.entries(rep)) S.factions[f] = clamp((S.factions[f] || 0) + n, -100, 300);
