    for (const g of S.ents.world.filter(e => e.morr && e.alive)) { g.afraid = clock() + 20; if ((g.seed * 10 | 0) % 2) float(g, pick(['Dodon!', 'DODON!', 'Groß-Mensch!']), 'rgba(230,200,120,ALPHA)'); }
    if (dod) dod.approach = true;
