const rotfallDesc = () => { const f = om().frags; return QUESTS.q_rotfall.desc.split(' Gefunden:')[0] + ' Gefunden: ' + (Object.keys(f).map(k => ROTFALL[k][0]).join(', ') || 'noch nichts') + '.'; };
