  S.gold -= 10; O.faith = Math.min(100, O.faith + (O.prayDay === (S.day | 0) ? 1 : 5) * (S.flags.feastDay === (S.day | 0) ? 2 : 1)); O.prayDay = S.day | 0;   // einmal am Tag zählt es richtig
