    if (near) { const O = (S.omega ||= { faith: 0, frags: {} }); O.faith = Math.min(100, (O.faith || 0) + 8); S.gold += 40; S.factions.chain = clamp((S.factions.chain || 0) + 5, -100, 100); log('Glaube +8, 40 Gold, Kette +5.', 'faction'); }
