    if (!A.ruins[k] || p.map !== 'world' || !S.razed?.[k]) continue;
    const [sx, sy] = TOWN_PLAN[k].square, d = Math.hypot(p.x / TS - sx, p.y / TS - sy), act0 = w => (S.contracts || []).some(c => c.ruin === k && c.ruinWhat === w && c.state === 'active');
