function loyAdd(m, n) { if (!m || m.friend && n < 0) return; if (n > 0) n *= 1 + (S.player?.skills?.leadership || 0) / 200; m.loyal = clamp(loyOf(m) + n, 0, 100); }   /* Audit A13: Führung beschleunigt Loyalität */
