function loreVoice(npc) { return [npc.key && 'n:' + npc.key, (npc.seaFolk || npc.seaCaptain) && 'x:sea', (npc.faction || (npc.undead ? 'undead' : '')) && 'f:' + (npc.faction || 'undead'), npc.prof && 'p:' + npc.prof].filter(Boolean); }
