  if (c.map !== 'world' && S.ents[c.map]?.some(s => s.lightShaft && Math.hypot(s.x - c.x, s.y - c.y) < 46)) { const h = hourNow(); return h >= 6 && h < 19 ? (hooded(c) ? 0.5 : 1) : 0; }   /* RB-030: Lichtschacht der Krypta brennt auch den Vampir-Spieler */
