    log(`Ein Bote: ${N.name} zieht gegen ${townName(home)}, wo deine Familie lebt!`, 'quest'); UI.toast(`${N.name.toUpperCase()} GREIFT ${townName(home).toUpperCase()} AN`, 3600);
