  stick.addEventListener('pointerdown', e => { e.preventDefault(); on(); sid = e.pointerId; cap(stick, e.pointerId); setStick(e); });
  stick.addEventListener('pointermove', e => { if (e.pointerId === sid) setStick(e); });
