// ================= Start =================
function buildCreation() {
  const pal = { skin: SKIN[0], hair: HAIR[0], cloth: CLOTH[0] };
  let origin = 'wanderer', build = 'ausgewogen';
  const bb = $('cr-builds'); bb.innerHTML = '';
  const pct = v => (v >= 1 ? '+' : '') + Math.round((v - 1) * 100) + ' %';
  const renderBuild = () => {
    const b = B.BUILDS[build];
    const parts = Object.entries(b.parts).map(([k, v]) => `${B.PART_NAME[k]} ${pct(v)}`);
    $('cr-build-desc').innerHTML = `${b.desc}<br><b>Tempo ${pct(b.speed)}</b> · Kopftreffer ${pct(b.headHit)}` +
      (b.stamina ? ` · Ausdauer ${b.stamina > 0 ? '+' : ''}${b.stamina}` : '') + (parts.length ? `<br>${parts.join(' · ')}` : '');
    drawPreview();
  };
  for (const [k, b] of Object.entries(B.BUILDS)) {
    const btn = el2('button', k === build ? 'sel' : '', b.name);
    btn.onclick = () => { build = k; [...bb.children].forEach(x => x.classList.remove('sel')); btn.classList.add('sel'); renderBuild(); };
    bb.appendChild(btn);
  }
  const ap = document.querySelector('.cr-appearance');
  const row = (label, arr, key) => {
    ap.appendChild(el2('label', '', label));
    const r = el2('div', 'swatchrow');
    arr.forEach((col, i) => {
      const s = el2('div', 'swatch' + (i === 0 ? ' sel' : '')); s.style.background = col;
      s.onclick = () => { pal[key] = col; [...r.children].forEach(x => x.classList.remove('sel')); s.classList.add('sel'); drawPreview(); };
      r.appendChild(s);
    });
    ap.appendChild(r);
  };
  ap.innerHTML = '';
  row('Haut', SKIN, 'skin'); row('Haar', HAIR, 'hair');
  pal.hs = 0;                                                        // Frisur (Pixel-Sprite)
  ap.appendChild(el2('label', '', 'Frisur'));
  const hr = el2('div', 'swatchrow');
  ['Kurz', 'Lang', 'Kahl', 'Zopf'].forEach((n, i) => {
    const b = el2('button', 'hairbtn' + (i === 0 ? ' sel' : ''), n);
    b.onclick = () => { pal.hs = i; [...hr.children].forEach(x => x.classList.remove('sel')); b.classList.add('sel'); drawPreview(); };
    hr.appendChild(b);
  });
  ap.appendChild(hr);
  row('Kleidung', CLOTH, 'cloth');
  let diff = 'schwer'; const db = $('cr-diff');                            // S15 P12: Schwierigkeit beim Start
  if (db) { db.innerHTML = ''; const showD = () => { $('cr-diff-desc').textContent = DIFF[diff].desc; };
    for (const [k, D] of Object.entries(DIFF)) { const b = el2('button', 'build' + (k === diff ? ' sel' : ''), D.name); b.onclick = () => { diff = k; [...db.children].forEach(x => x.classList.remove('sel')); b.classList.add('sel'); showD(); }; db.appendChild(b); }
    showD(); }
  let startAt = 'varonheim'; const sb = $('cr-start');                  /* Varonheim-Umbau S5: Startort, Vorgabe Hauptstadt */
  if (sb) { sb.innerHTML = ''; const showS = () => { $('cr-start-desc').textContent = START_AT[startAt].desc; };
    for (const [k, D] of Object.entries(START_AT)) { const b = el2('button', 'build' + (k === startAt ? ' sel' : ''), D.name); b.onclick = () => { startAt = k; [...sb.children].forEach(x => x.classList.remove('sel')); b.classList.add('sel'); showS(); }; sb.appendChild(b); }
    showS(); }
  const ob = $('cr-origins'); ob.innerHTML = '';
  for (const [k, o] of Object.entries(ORIGINS)) {
    const b = el2('button', 'origin' + (k === origin ? ' sel' : ''), `${o.name}<small>${Object.keys(o.skills).slice(0, 2).map(s => SKILL_NAMES[s] || s).join(', ')}</small>`);
    b.onclick = () => { origin = k; [...ob.children].forEach(x => x.classList.remove('sel')); b.classList.add('sel'); renderOrigin(); };
    ob.appendChild(b);
  }
  function renderOrigin() {
    const o = ORIGINS[origin];
    $('cr-origin-desc').textContent = o.desc;
    const base = baseAttrs();
    $('cr-attrs').innerHTML = Object.entries({ strength:'Stärke', agility:'Beweglichkeit', endurance:'Ausdauer',
      intelligence:'Intelligenz', perception:'Wahrnehmung', willpower:'Willenskraft' })
      .map(([k, n]) => `<div class="attr-row"><span>${n}</span><b>${base[k] + (o.attrs[k] || 0)}${o.attrs[k] ? ` <span style="color:#89a05a">+${o.attrs[k]}</span>` : ''}</b></div>`).join('');
    $('cr-start-gear').innerHTML = `<b>Ausrüstung</b><br>${o.gear.map(g => ITEMS[g].name).join('<br>')}<br><br><b>Gold</b> ${o.gold}`;
    drawPreview();
  }
  function drawPreview() {
    const cv = $('cr-preview'), c = cv.getContext('2d');
    c.clearRect(0, 0, cv.width, cv.height);
    c.fillStyle = '#14110d'; c.fillRect(0, 0, cv.width, cv.height);
    const g = c.createRadialGradient(80, 100, 4, 80, 140, 140);
    g.addColorStop(0, 'rgba(120,95,60,.35)'); g.addColorStop(1, 'rgba(0,0,0,0)');
    c.fillStyle = g; c.fillRect(0, 0, cv.width, cv.height);
    c.save(); c.translate(80, 200); c.scale(3.4, 3.4);
    const eq = {};                                                    // Vorschau trägt die Startausrüstung der Herkunft
    for (const k of ORIGINS[origin].gear) { const sl = ITEMS[k].slot; if (['weapon', 'offhand', 'head', 'chest', 'cloak'].includes(sl) && !eq[sl]) eq[sl] = { key: k }; }
    if (!eq.weapon) eq.weapon = { key: 'rusty_sword' };
    R.drawHumanoid({ kind:'player', x:0, y:0, pal, facing:0, seed:1, build, equip: eq, aim: Math.PI / 2 - 0.35 }, performance.now(), c);   // Phase 1: 3/4-Ansicht von vorn (vorher 0.5 = Seitenprofil)
    c.restore();
  }
  renderOrigin(); renderBuild();
  setInterval(() => { if ($('creation') && !$('creation').classList.contains('hidden')) drawPreview(); }, 200);   /* RB-056 */
  $('cr-begin').onclick = () => {
    const name = ($('cr-name').value || 'Namenlos').slice(0, 18);
    const house = ($('cr-house').value || name).slice(0, 18);
    if (creation.hook) { const h = creation.hook; creation.hook = creation.back = null; $('creation').classList.add('hidden'); if (!running) $('titlescreen').classList.remove('hidden'); return h({ name, house, origin, pal: { ...pal }, build }); }   /* Koop: der Gast erstellt seinen eigenen Charakter */
    bindInput();
    newGame({ name, house, origin, pal, build, difficulty: diff, start: startAt });
  };
  $('cr-back').onclick = () => { $('creation').classList.add('hidden'); if (!running) $('titlescreen').classList.remove('hidden'); const b = creation.back; creation.hook = creation.back = null; b?.(); };
}
// Koop (Nutzer): Ein Spieler am Boden stirbt nicht, solange ein anderer Spieler (Held oder Mitspieler) noch steht — der kann ihn
// aufrichten. Erst wenn alle Spieler am Boden sind, läuft der Tod wie immer (Held: Erbe wählen; Mitspieler: im Warteraum neu).
function coopHold(c) {
  const players = [S.player, ...partyMembers().filter(m => m.coopPilot)];
  if (players.length < 2 || !players.includes(c)) return false;
  return players.some(o => o !== c && o.alive && !o.downed && o.map === c.map);
}
// Koop: Charaktererstellung für einen Gast öffnen. done(cfg) bekommt Name, Herkunft, Aussehen, Körperbau; back() beim Zurück.
const creation = { hook: null, back: null };
const GUEST_BAR = ['bandage', 'potion', 'herb', 'bread', 'dried_meat'];   /* Koop: Leiste der Gastfigur (nur Verbrauchsgüter; Fähigkeiten löst nur der Held aus) */
function openCreation(done, back, name) { creation.hook = done; creation.back = back; if (name) $('cr-name').value = name; $('titlescreen').classList.add('hidden'); $('creation').classList.remove('hidden'); }
// Koop: der eigene Charakter eines Gasts. Gebaut wie der Held in newGame (Herkunft: Werte, Fertigkeiten, Ausrüstung, Gold als Beutel),
// aber als Gruppenmitglied. Er fängt zwei Stufen unter dem Helden an, damit er mithalten kann. coopOwner = Name des Gasts.
function makeGuestHero(cfg, owner) {
  const o = ORIGINS[cfg.origin] || ORIGINS.wanderer, p0 = S.player, q = { x: p0.x + (solidTile(p0.map, p0.x + 28, p0.y) ? -28 : 28), y: p0.y }   /* direkt neben den Helden (freeSpotNear sucht in Städten große freie Flächen und landete weit weg) */;
  const h = makeChar({ kind: 'npc', key: 'coop_' + owner, name: String(cfg.name || owner).slice(0, 18), x: q.x, y: q.y, map: p0.map, level: cfg.level || Math.max(1, (p0.level || 1) - 2),
    attrs: baseAttrs(), skills: { ...o.skills }, traits: [pick(['mutig', 'neugierig', 'diszipliniert', 'ehrgeizig'])], origin: o.name, pal: cfg.pal, build: cfg.build || 'ausgewogen' });
  h.attributes = Object.fromEntries(Object.entries(h.attributes).map(([k, v]) => [k, v + (o.attrs[k] || 0)]));
  Object.assign(h, { prof: o.name, coopHero: true, coopOwner: owner, coopGold: o.gold, morale: 100, hotbar: GUEST_BAR.map(key => ({ type: 'item', key })), transient: false, visitor: false });
  h.xpNext = Math.round(60 * Math.pow(1.35, Math.min(9, h.level - 1)) * Math.pow(1.2, Math.max(0, h.level - 10)));
  o.gear.forEach(k => { const it = mkItem(k), sl = ITEMS[k].slot; if (['weapon', 'chest', 'offhand'].includes(sl) && !h.equip[sl]) h.equip[sl] = it; else addItem(h, k); });
  addItem(h, 'bandage', 2); recalc(h); B.fullHeal(h); h.mana = h.maxMana;
  S.ents[h.map].push(h); S.party.push(h.id); return h;
}
// Koop: Gastcharaktere ohne verbundenen Gast warten in S.coopHeroes (gespeichert), nicht in der Welt oder Gruppe.
function parkCoopHero(h) { if (!h) return; for (const k of Object.keys(S.ents)) S.ents[k] = S.ents[k].filter(e => e !== h); S.party = S.party.filter(id => id !== h.id);
  h.coopPilot = null; h.coopName = null; h.vx = h.vy = 0; h.dodge = null; (S.coopHeroes ||= {})[h.coopOwner] = h; }
function unparkCoopHero(owner) { const h = S.coopHeroes?.[owner]; if (!h) return null; delete S.coopHeroes[owner]; const p0 = S.player, q = { x: p0.x + (solidTile(p0.map, p0.x + 28, p0.y) ? -28 : 28), y: p0.y }   /* direkt neben den Helden (freeSpotNear sucht in Städten große freie Flächen und landete weit weg) */;
  Object.assign(h, { map: p0.map, x: q.x, y: q.y }); if (!h.alive) return null; S.ents[h.map].push(h); S.party.push(h.id); return h; }
function el2(tag, cls, html) { const e = document.createElement(tag); if (cls) e.className = cls; if (html != null) e.innerHTML = html; return e; }

function titleLoop(t) {
  if ($('titlescreen').classList.contains('hidden')) return;
  if (titleLoop.hero === undefined) { try { const d = loadRaw(), pl = d && Object.values(d.ents || {}).flat().find(e => e && e.kind === 'player'); titleLoop.hero = pl || null; if (d?.settings?.art) SP.setArt(d.settings.art); R.setTitleHero(pl); } catch { titleLoop.hero = null; } }   // Phase 1: eigener Charakter am Feuer
  R.drawTitleScene($('titlecanvas'), t);
  requestAnimationFrame(titleLoop);
}

// Koop K2: alles, was src/coop.js aus dem Spiel braucht, an einer Stelle (kein zweiter Import-Kreis)
// Nutzer (30.09.2026): Spielstände. Liste je Art (Einzelspieler / Koop), jede Karte mit Held, Haus, Stufe, Tag, Generation und
// Erfolgs-Symbolen (Garmadon tot = Schädel usw., Tooltip nennt den Erfolg). Laden setzt den aktiven Platz, Löschen fragt nach.
function slotCards(mode, onLoad, again = true) {
  const idx = slotIndex(), list = Object.values(idx).filter(x => (x.mode || 'single') === mode).sort((a, b) => (b.at || 0) - (a.at || 0));
  let pending = false;   /* RB-009: gepackter Stand aus einem anderen Tab — erst entpacken, dann neu zeigen */
  for (const x of list) if (x.name == null) { const r = readRaw(slotKey(x.id)); if (r == null && localStorage.getItem(slotKey(x.id))) { x.name = '…'; pending = true; continue; }
    try { Object.assign(x, slotMetaFrom(JSON.parse(r))); } catch (e) { x.name = '?'; } }   /* alter Stand ohne Übersicht */
  const esc = t => String(t ?? '').replace(/[<>&"]/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;' })[c]);
  const html = list.length ? list.map(x => `<div class="slot-card${x.id === SLOT ? ' active' : ''}"><div class="sl-head"><b>${esc(x.name)}</b> <span>${esc(x.house ? 'Haus ' + x.house : '')}</span></div>
    <div class="sl-sub">Stufe ${x.level || 1} · Tag ${x.day || 1} · Generation ${x.gen || 1}${x.dead ? ' · gefallen' : ''}${x.at ? ' · ' + new Date(x.at).toLocaleString('de-DE', { dateStyle: 'short', timeStyle: 'short' }) : ''}</div>
    <div class="sl-marks">${(x.marks || []).map(k => { const a = ACHIEVE.find(q => q[0] === k); return a ? `<span title="${esc(a[2])}">${a[1]}</span>` : ''; }).join('') || '<span class="sl-none">noch keine großen Taten</span>'}</div>
    <div class="sl-act"><button class="plaque" data-load="${x.id}">${mode === 'coop' ? 'Hosten' : 'Laden'}</button><button class="plaque ghost" data-del="${x.id}">Löschen</button></div></div>`).join('')
    : `<p class="ledger">Noch kein ${mode === 'coop' ? 'Koop-' : ''}Spielstand.</p>`;
  const wrap = document.createElement('div'); wrap.className = 'slot-list'; wrap.innerHTML = html;
  wrap.querySelectorAll('[data-load]').forEach(b => b.onclick = async () => { await unpackAll(); onLoad(b.dataset.load); });   /* RB-009: Stand frisch entpacken (anderer Tab) */
  if (pending && again) unpackAll().then(() => { if (wrap.isConnected) wrap.replaceWith(slotCards(mode, onLoad, false)); });   /* nur ein Versuch: kaputter Stand bleibt „…“ */
  wrap.querySelectorAll('[data-del]').forEach(b => b.onclick = () => { const x = idx[b.dataset.del]; if (!confirm(`Spielstand „${x?.name || '?'}“ endgültig löschen?`)) return; deleteSlot(b.dataset.del); wrap.replaceWith(slotCards(mode, onLoad)); });
  return wrap;
}
function slotPanel(mode) {
  let el = $('slot-panel'); if (!el) { el = document.createElement('div'); el.id = 'slot-panel'; document.body.appendChild(el); }
  el.innerHTML = `<div class="coop-box"><h2>Spielstände</h2><p class="ledger">Einzelspieler. Koop-Spielstände stehen getrennt im Koop-Fenster. Die Symbole zeigen, was in diesem Stand schon geschafft ist (Maus darüber).</p><div id="slot-host"></div><button class="plaque" id="slot-new">Neue Geschichte</button><button class="plaque" id="slot-close">Schließen</button></div>`;
  el.classList.remove('hidden');
  $('slot-host').appendChild(slotCards(mode, id => { el.classList.add('hidden'); setSlot(id); titleLoop.hero = undefined; bindInput(); continueGame(); }));
  $('slot-close').onclick = () => el.classList.add('hidden');
  $('slot-new').onclick = () => { el.classList.add('hidden'); document.querySelector('[data-act="new"]').click(); };
}
function coopAPI() {
  return { S, R, UI, B, MAPS, TS, coopHooks, keys, mouse, log, onLog, byId, partyMembers, dist, saveData, applySave, hasSave, continueGame, bindInput,
    isRunning: () => running, slotCards, setSlot, newSlot, slotIndex, SLOT: () => SLOT, moveInput, moveEnt, speedOf, attack, hostilesOf, updateGuard, updateFx, fx, DODGE, equip, unequip, useConsumable, dropItemAt, doInteractFor, useSlotFor, stepHidden, giveItem, questGold, ITEMS, addItem, price, shopStock, ecoTown, travelVia, shopRefusal, openCreation, loadRaw, CLASSES, revealAround, townName, FIRST_M, SKIN, HAIR, CLOTH, updatePrompt, recalc, talk, QUESTS, doInteract, GUEST_BAR, makeGuestHero, parkCoopHero, unparkCoopHero, ORIGINS, dialogue: (...a) => UI.dialogue(...a), clock };
}
function boot() {
  UI.initUI();
  UI.bind({
    select: e => { selected = e; UI.renderContext(e); },
    talk, recruit, dismiss, giveGear, partyCommand, repairAll, wxText: () => WX[wxKey()]?.txt || '',
    openCoop: () => import('./coop.js?v=23').then(m => m.openPanel(coopAPI())).catch(err => UI.toast('Koop nicht ladbar: ' + err.message, 4000)),   /* Koop K2: auch im Spiel über die Einstellungen */
    useOrEquip: i => coopHooks.cmd?.({ kind: 'equip', idx: i }) ?? equip(S.player, i),   /* Koop: beim Gast führt der Host es aus */
    unequip: k => coopHooks.cmd?.({ kind: 'unequip', slot: k }) ?? unequip(S.player, k),
    dropItem: i => { if (coopHooks.cmd?.({ kind: 'drop', idx: i })) return; const s = S.player.inv[i]; if (!s) return; dropItemAt(S.map, S.player.x + 16, S.player.y + 8, s); S.player.inv.splice(i, 1); },
    toStash: i => { if (coopHooks.cmd) return UI.toast('Das Lager gehört dem Host.'); const s = S.player.inv[i]; if (!s) return; S.stash.push(s); S.player.inv.splice(i, 1); },
    takeFromStash,
    toHotbar: key => { const p = S.player, e = { type:'item', key }, i = p.hotbar.findIndex(s => !s); if (i >= 0) p.hotbar[i] = e; else if (p.hotbar.length < 10) p.hotbar.push(e); else p.hotbar[9] = e; UI.renderHotbar(); },   // S13: freie (entfernte) Plätze zuerst
    useSlot, spendAttr: k => { if (coopHooks.cmd?.({ kind: 'attr', key: k })) return; const p = S.player; if (p.attrPoints > 0) { p.attributes[k]++; p.attrPoints--; recalc(p); } },
    setClass, setTitleClass, tres, resMax, learnNode, nodeState, armorOf, damageOf, population, canAfford,
    startPlacing, foundCamp: () => foundCamp(),
    raisePriority: i => { const pr = S.settlement.priorities; if (i > 0) { const t = pr[i]; pr[i] = pr[i - 1]; pr[i - 1] = t; } },
    offers: npcOffers,   // S13: was eine Figur anbietet (Infofeld)
    effects: activeEffects, fxDesc: FX_DESC, rankGuide, zoneRange: (map, tx, ty) => ZONE[clamp(zoneTier(map, tx, ty), 0, 5)],   // S13: Gegnerstufen je Gebiet sichtbar
    questInfo, cancelQuest, trackQuest: k => { S.track = k; },
    shopStock, price, buy, sell, craftBandage, bandageFrom: k => BANDAGE_FROM[k] || 0,
    bandage: (target, part) => {
      const idx = S.player.inv.findIndex(x => x.key === 'bandage');
      if (idx < 0) return UI.toast('Keine Verbände. Kaufen, finden oder aus Stoff herstellen.');
      if (target !== S.player && dist(S.player, target) > 70) return UI.toast(`${target.name} ist zu weit weg.`);
      useConsumable(S.player, idx, target, part);
    },
    drawWorldmap, mapPick, drawWarmap, warStatus, facRelation, repTier,
    spellTeachers,                                                     // S15 P5: Kodex „Magie“, Zauberbuch
    magicView: MAGIC_VIEW, coreSmash,                                             // S15 P7
    fameList: () => Object.entries(FAME_REG).map(([k, n]) => ({ k, n, v: fameOf(k), t: fameTier(fameOf(k)) })),
    priceNote: (k, npc) => priceNote(k, npc),   /* T09 */
    styleList: () => Object.entries(FAME_REG).filter(([k]) => styleOf(k)).map(([k, n]) => ({ n, v: Math.round(styleOf(k)), t: styleTier(styleOf(k)) })),   /* T08 Ruf der Klinge */   // S15 P8
    difficulty: () => DIFF[S.difficulty || 'schwer'],                  // S15 P12
    mountInfo: () => { const H = mountStats(); return H && { name: H.name, tempo: Math.round(H.tempo * 100), stamina: Math.round(H.stamina ?? H.staminaMax), staminaMax: H.staminaMax, mut: H.mut, kind: MOUNTS[H.kind]?.name }; }, releaseMount,   // S15 P17
    stableOffers, buyHorse: (npc, id) => { const ok = buyHorse(npc, id); if (ok) mountIntro(npc); return ok; }, horseValue, mountStats,   // S15 Stall
    codexKnown: (kind, k) => !!(S.flags.codexAll || S.codex?.[kind]?.[k]), codexCode: c => { if (String(c).trim().toUpperCase() !== 'NACHTGLAS') return false; S.flags.codexAll = true; return true; },   // S15 Kodex
    teacherList: () => S.ents.world.filter(e => e.kind === 'npc' && e.alive && e.teaches).map(e => ({ key: e.key, name: e.name, prof: e.prof, cls: [].concat(e.teaches), where: LOCATIONS.slice().sort((a, b) => Math.hypot(a.x - e.x / TS, a.y - e.y / TS) - Math.hypot(b.x - e.x / TS, b.y - e.y / TS))[0]?.name || '—' })),   // S15: Kodex „Lehrer“
    saveNow: () => saveCompressed(),   /* Control-Befund: komprimiert, sonst scheitert es bei knappem Speicher */ setArt: v => SP.setArt(v), schools: SCHOOL, spellKeys: SPELL_KEYS, spellToBar: k => spellToBar(k),   // S15 P4: Zauberbuch   // Nutzer S13: Grafikstil
  });
  // Titelbildschirm
  $('legacy-summary').innerHTML = hasSave() ? (() => {
    const d = loadRaw();
    if (!d) return '';
    return `AKTUELLES ERBE<br><br>Haus ${d.legacy.house}<br>Generation ${d.legacy.gen}<br><br>
      Aktueller Charakter:<br>${d.player?.name || '—'}<br><br>Tag ${d.day}`;
  })() : 'Noch keine Geschichte geschrieben.';
  { const last = localStorage.getItem('rotfall.slot.lastSingle'); if (SLOT.startsWith('c') && last && slotIndex()[last]) setSlot(last); }   /* Titel: Einzelspieler-Stand aktiv */
  document.querySelector('[data-act="continue"]').disabled = !hasSave() || SLOT.startsWith('c');
  document.querySelectorAll('.menu-plaques .plaque').forEach(b => {
    b.onclick = () => {
      const act = b.dataset.act;
      if (act === 'continue') { const last = localStorage.getItem('rotfall.slot.lastSingle'); if (SLOT.startsWith('c') && last && slotIndex()[last]) setSlot(last); bindInput(); continueGame(); }   /* Fortsetzen = letzter Einzelspieler-Stand */
      else if (act === 'slots') { slotPanel('single'); }
      else if (act === 'coop') { import('./coop.js?v=23').then(m => m.openPanel(coopAPI())).catch(err => UI.toast('Koop nicht ladbar: ' + err.message, 4000)); }   /* Koop K2, nur auf Knopfdruck geladen */
      else if (act === 'new') { setSlot(newSlot('single'));   /* Nutzer: neue Geschichte bekommt einen eigenen Platz, nichts wird überschrieben (vorher BUG-086-Rückfrage) */
        $('titlescreen').classList.add('hidden'); $('creation').classList.remove('hidden'); }
      else if (act === 'chronicle') { UI.openModal('chronicle'); }
      else if (act === 'settings') { UI.openModal('settings'); }
    };
  });
  buildCreation();
  requestAnimationFrame(titleLoop);
  if (location.search.includes('test')) setTimeout(() => selftest(), 400);
  // Entwicklerzugang (nur mit ?dev): Zustand und Kernfunktionen für Browser-Tests; tick() simuliert auch bei verstecktem Tab.
  if (location.search.includes('dev')) window.RF = { S, R, MAPS, TS, update, die, capital2Migrate, useConsumable, foeFacs, lureWhistle, craftItem, craftMenu, coopHooks, coopAPI, coop: { fakeGuest: entId => import('./coop.js?v=23').then(m => m.fakeGuest(coopAPI(), entId)) }, loadProbe, gesture, deathKind, seaVoyage, airVoyage, ensureAirport, harborTalk, voyageFix, airRepair, airUpgrade, tributeDay, tribState, startBrawl, spawnTribute, fortressHour, campaignDay, campTick, planCampaign, festTick, controlPlayer, updateFx, updateProjectiles, actorsOf, think, questPoint, talk, goToJail, jailTick, townContracts, acceptContract, conTick, makeContract, findPath, startHunt, huntTick, courtTrial, travel, skyGate, enslave, bondTick, freeBond, aurelWatch, hasPermit, inAurel, mechMenu, raidDay, raidTick, raze, defPower, startRunaway, chainTick, unlockClass, separate, combatN: () => combat.length, factoryWork, holyCourt, aurelParade, mechSwapOptions, councilVote, applyLaw, councilSession, corvanTalk, refugeeWave, TOPICS, cinematic, vargCinematic, undeadFallCinematic, vharnholmFate, cineEnd, healTick, omegaStance, faithDay, ketzerjagd, wallfahrt, kreuzzug, opferfest, growTown, growthDay, investMenu, omegaFrag, omegaPerform, omegaEnd, ensureOmegaBoss, garmadonHost, garmadonParley, garmadonSlain, spawnEnemy, magitechAccident, isHostile, furnAct, useFurniture, sleepIn, rummage, tradeAt, makeChar, HOUSES, B, styleArea, dayTarget, placeAway, VILLAGERS, tick: (ms, step = 16) => { for (let t = 0; t < ms; t += step) update(step, performance.now()); },
    travel, spawnEnemy, hurt, die, downed, provoke, attack, resolveSwing, teamOf, isHostile, byId, save, selftest, solidPropAt, solidIndex, spawnChoiceEncounter, encTalk, ambientTick, runScene, ensureCoaches, tripOf, journey, applyVariant, rallyCall, enterVault, buildVault, twinFallCheck, legionArrives, duel, simFight, mkItem, equip, ECO, ecoMenu, dayTick, spawnTraveler, travelerStep, roadTick, migrationDay, emigrate, settleIn, eatMeal, marketBuy, dayTargetRaw, TRAV_KINDS,
    figSheet: (name, list, o) => figSheet(name, list.map(([l, k, w]) => [l, typeof k === 'string' ? sheetSpec(k) : k, w]).filter(r => r[1]), o),
    castSpell, learnSpell, spellMenu, startTrial, acadSpot, spellHit, spellPower, stableOffers, buyHorse, dkSteed,                                           // S15 P4: Zauber im Dev-Modus prüfen
    shot: async name => { R.resize(); R.drawFrame(performance.now()); const url = document.getElementById('game-canvas').toDataURL('image/png'); return (await fetch('http://127.0.0.1:8771/' + name + '.png', { method: 'POST', body: url })).status; } };   // Bildschirmfoto in docs/screenshots (Sichtprüfung)
}
await unpackAll();   /* Audit D6: komprimierte Spielstände vor dem Titelbild entpacken (Laden bleibt synchron) */
boot();
